import{_ as e,o as a,c as n,a0 as t}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"模块开发指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/guide/module.md","filePath":"zh_CN/guide/module.md"}'),i={name:"zh_CN/guide/module.md"};function l(o,s,p,d,c,r){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="introduction" tabindex="-1">模块开发指南 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;模块开发指南 {#introduction}&quot;">​</a></h1><p>KernelSU 提供了一个模块机制，它可以在保持系统分区完整性的同时达到修改系统分区的效果；这种机制通常被称之为 systemless。</p><p>KernelSU 的模块运作机制与 Magisk 几乎是一样的，如果你熟悉 Magisk 模块的开发，那么开发 KernelSU 的模块大同小异，你可以跳过下面有关模块的介绍，只需要了解 <a href="./difference-with-magisk.html">KernelSU 模块与 Magisk 模块的异同</a>。</p><div class="warning custom-block"><p class="custom-block-title">仅修改系统文件需要 METAMODULE</p><p>KernelSU 使用 <a href="./metamodule.html">metamodule</a> 架构来挂载 <code>system</code> 目录。<strong>只有当您的模块需要修改 <code>/system</code> 文件</strong>（通过 <code>system</code> 目录）时，才需要安装 metamodule（例如 <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>）。其他模块功能如脚本、sepolicy 规则和 system.prop 无需 metamodule 即可工作。</p></div><h2 id="模块界面" tabindex="-1">模块界面 <a class="header-anchor" href="#模块界面" aria-label="Permalink to &quot;模块界面&quot;">​</a></h2><p>KernelSU 的模块支持显示界面并与用户交互，请参阅 <a href="./module-webui.html">WebUI 文档</a>。</p><h2 id="模块配置" tabindex="-1">模块配置 <a class="header-anchor" href="#模块配置" aria-label="Permalink to &quot;模块配置&quot;">​</a></h2><p>KernelSU 提供了一个内置的配置系统，允许模块存储持久化或临时的键值设置。详情请参阅<a href="./module-config.html">模块配置文档</a>。</p><h2 id="一次性脚本" tabindex="-1">一次性脚本 <a class="header-anchor" href="#一次性脚本" aria-label="Permalink to &quot;一次性脚本&quot;">​</a></h2><p>模块 ZIP 也可以是一次性脚本：KernelSU 管理器只运行它一次，而不是安装它。详情请参阅<a href="./module-script.html">一次性脚本文档</a>。</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>KernelSU 提供了一个功能完备的 BusyBox 二进制文件（包括完整的 SELinux 支持）。可执行文件位于 <code>/data/adb/ksu/bin/busybox</code>。 KernelSU 的 BusyBox 支持运行时可切换的 &quot;ASH Standalone Shell Mode&quot;。 这种独立模式意味着在运行 BusyBox 的 ash shell 时，每个命令都会直接使用 BusyBox 中内置的应用程序，而不管 PATH 设置为什么。 例如，<code>ls</code>、<code>rm</code>、<code>chmod</code> 等命令将不会使用 PATH 中设置的命令（在 Android 的情况下，默认情况下分别为 <code>/system/bin/ls</code>、<code>/system/bin/rm</code> 和 <code>/system/bin/chmod</code>），而是直接调用 BusyBox 内置的应用程序。 这确保了脚本始终在可预测的环境中运行，并始终具有完整的命令套件，无论它运行在哪个 Android 版本上。 要强制一个命令不使用 BusyBox，你必须使用完整路径调用可执行文件。</p><p>在 KernelSU 上下文中运行的每个 shell 脚本都将在 BusyBox 的 ash shell 中以独立模式运行。对于第三方开发者相关的内容，包括所有启动脚本和模块安装脚本。</p><p>对于想要在 KernelSU 之外使用这个“独立模式”功能的用户，有两种启用方法:</p><ol><li>设置环境变量 <code>ASH_STANDALONE</code> 为 <code>1</code>。例如：<code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>使用命令行选项切换：<code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>为了确保所有后续的 <code>sh</code> shell 都在独立模式下执行，第一种是首选方法（这也是 KernelSU 和 KernelSU 管理器内部使用的方法），因为环境变量会被继承到子进程中。</p><div class="tip custom-block"><p class="custom-block-title">与 Magisk 的差异</p><p>KernelSU 的 BusyBox 现在是直接使用 Magisk 项目编译的二进制文件，<strong>感谢 Magisk！</strong> 因此，你完全不用担心 BusyBox 脚本与在 Magisk 和 KernelSU 之间的兼容问题，因为他们是完全一样的！</p></div><h2 id="kernelsu-modules" tabindex="-1">KernelSU 模块 <a class="header-anchor" href="#kernelsu-modules" aria-label="Permalink to &quot;KernelSU 模块 {#kernelsu-modules}&quot;">​</a></h2><p>KernelSU 模块就是一个放置在 <code>/data/adb/modules</code> 内且满足如下结构的文件夹：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- 模块的文件夹名称与模块 ID 相同</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 模块配置文件 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- 此文件保存模块相关的一些配置，如模块 ID、版本等</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 模块内容 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- 这个文件夹通常会被挂载到系统</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 标记文件 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- 如果这个文件存在，那么模块的 \`/system\` 将不会被挂载</span></span>
<span class="line"><span>│   ├── disable             &lt;--- 如果这个文件存在，那么模块会被禁用</span></span>
<span class="line"><span>│   ├── remove              &lt;--- 如果这个文件存在，下次重启的时候模块会被移除</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 可选文件 ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- 这个脚本将会在 post-fs-data 模式下运行</span></span>
<span class="line"><span>│   ├── post-mount.sh       &lt;--- 这个脚本将会在 post-mount 模式下运行</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- 这个脚本将会在 late_start 服务模式下运行</span></span>
<span class="line"><span>│   ├── boot-completed.sh   &lt;--- 这个脚本将会在 Android 系统启动完毕后以服务模式运行</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- 这个脚本将会在模块被卸载时运行</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- 这个文件中指定的属性将会在系统启动时通过 resetprop 更改</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- 这个文件中的 SELinux 策略将会在系统启动时加载</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- 此目录下的 .rc 文件将在启动时注入 init.rc</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   ├── preinit/            &lt;--- preinit.conf 及其文件，在 SELinux 策略加载前执行</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** 自动生成的目录，不要手动创建或者修改！ ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- 如果 /system/vendor 是符号链接且存在，从 $MODID/system/vendor 移动到模块根目录</span></span>
<span class="line"><span>│   ├── product             &lt;--- 如果 /system/product 是符号链接且存在，从 $MODID/system/product 移动到模块根目录</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- 如果 /system/system_ext 是符号链接且存在，从 $MODID/system/system_ext 移动到模块根目录</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Any additional files / folders are allowed ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">与 Magisk 的差异</p><p>KernelSU 没有内置的针对 Zygisk 的支持，因此模块中没有 Zygisk 相关的内容，但你可以通过 <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> 来支持 Zygisk 模块，此时 Zygisk 模块的内容与 Magisk 所支持的 Zygisk 是完全相同的。</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop 是一个模块的配置文件，在 KernelSU 中如果模块中不包含此文件，那么它将不被认为是一个模块；此文件的格式如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li>id 必须与这个正则表达式匹配：<code>^[a-zA-Z][a-zA-Z0-9._-]+$</code> 例如：✓ <code>a_module</code>，✓ <code>a.module</code>，✓ <code>module-101</code>，✗ <code>a module</code>，✗ <code>1_module</code>，✗ <code>-a-module</code>。这是您的模块的唯一标识符，发布后不应更改。</li><li>versionCode 必须是一个整数，用于比较版本。</li><li>其他未在上面提到的内容可以是任何单行字符串。</li><li>请确保使用 UNIX（LF）换行类型，而不是 Windows（CR + LF）或 Macintosh（CR）。</li><li>actionIcon 和 webuiIcon 是可选的图标路径，用作管理器中模块 Action 快捷方式和 WebUI 快捷方式的默认图标。这些路径必须是基于模 块根目录的相对路径。例如 <code>actionIcon=icon/icon.png</code> 将会解析为 <code>&lt;MODDIR&gt;/icon/icon.png</code>。</li></ul><div class="tip custom-block"><p class="custom-block-title">动态描述</p><p><code>description</code> 字段可以在运行时使用模块配置系统动态覆盖。详情请参阅<a href="./module-config.html#overriding-module-description">覆盖模块描述</a>。</p></div><h3 id="shell-scripts" tabindex="-1">Shell 脚本 <a class="header-anchor" href="#shell-scripts" aria-label="Permalink to &quot;Shell 脚本 {#shell-scripts}&quot;">​</a></h3><p>请阅读 <a href="#boot-scripts">启动脚本</a> 一节，以了解 <code>post-fs-data.sh</code>, <code>post-mount.sh</code>, <code>service.sh</code> 和 <code>boot-completed.sh</code> 之间的区别。对于大多数模块开发者来说，如果您只需要运行一个启动脚本，<code>service.sh</code> 应该已经足够了。</p><p>在您的模块的所有脚本中，请使用<code>MODDIR=\${0%/*}</code>来获取您的模块的基本目录路径；请勿在脚本中硬编码您的模块路径。</p><div class="tip custom-block"><p class="custom-block-title">与 Magisk 的差异</p><p>你可以通过环境变量 <code>KSU</code> 来判断脚本是运行在 KernelSU 还是 Magisk 中，如果运行在 KernelSU，这个值会被设置为 <code>true</code>。</p></div><h3 id="system-directories" tabindex="-1"><code>system</code> 目录 <a class="header-anchor" href="#system-directories" aria-label="Permalink to &quot;\`system\` 目录 {#system-directories}&quot;">​</a></h3><p>这个目录的内容会在系统启动后，以 <code>overlayfs</code> 的方式叠加在系统的 <code>/system</code> 分区之上，这意味着：</p><ol><li>系统中对应目录的同名文件会被此目录的文件覆盖。</li><li>系统中对应目录的同名文件夹会与此目录的文件夹合并。</li></ol><p>如果你想删掉系统原来目录某个文件或者文件夹，你需要在模块目录通过 <code>mknod filename c 0 0</code> 来创建一个 <code>filename</code> 的同名文件；这样 overlayfs 系统会自动 whiteout 等效删除此文件（<code>/system</code> 分区并没有被更改）。</p><p>你也可以在 <code>customize.sh</code> 中声明一个名为 <code>REMOVE</code> 并且包含一系列目录的变量来执行删除操作，KernelSU 会自动为你在模块对应目录执行 <code>mknod &lt;TARGET&gt; c 0 0</code>。例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>上面的这个列表将会执行： <code>mknod $MODPATH/system/app/YouTuBe c 0 0</code> 和 <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>；并且 <code>/system/app/YouTube</code> 和 <code>/system/app/Bloatware</code> 将会在模块生效后被删除。</p><p>如果你想替换掉系统的某个目录，你需要在模块目录创建一个相同路径的目录，然后为此目录设置此属性：<code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code>；这样 overlayfs 系统会自动将系统内相应目录替换（<code>/system</code> 分区并没有被更改）。</p><p>你可以在 <code>customize.sh</code> 中声明一个名为 <code>REPLACE</code> 并且包含一系列目录的变量来执行替换操作，KernelSU 会自动为你在模块对应目录执行相关操作。例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REPLACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>上面这个列表将会：自动创建目录 <code>$MODPATH/system/app/YouTube</code> 和 <code>$MODPATH//system/app/Bloatware</code>，然后执行 <code>setfattr -n trusted.overlay.opaque -v y $$MODPATH/system/app/YouTube</code> 和 <code>setfattr -n trusted.overlay.opaque -v y $$MODPATH/system/app/Bloatware</code>；并且 <code>/system/app/YouTube</code> 和 <code>/system/app/Bloatware</code> 将会在模块生效后替换为空目录。</p><div class="tip custom-block"><p class="custom-block-title">与 Magisk 的差异</p><p>KernelSU 的 systemless 机制是通过内核的 overlayfs 实现的，而 Magisk 当前则是通过 magic mount (bind mount)，二者实现方式有着巨大的差异，但最终的目标实际上是一致的：不修改物理的 <code>/system</code> 分区但实现修改 <code>/system</code> 文件。</p></div><p>如果你对 overlayfs 感兴趣，建议阅读 Linux Kernel 关于 <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">overlayfs 的文档</a></p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>这个文件的格式与 <code>build.prop</code> 完全相同：每一行都是 <code>[key]=[value]</code> 的形式。</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>如果您的模块需要一些额外的 SELinux 策略补丁，请将这些规则添加到此文件中。这个文件中的每一行都将被视为一个策略语句。</p><h3 id="initrc-injection" tabindex="-1">initrc 注入 <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;initrc 注入 {#initrc-injection}&quot;">​</a></h3><p>KernelSU 提供了一种将自定义 Android Init RC 指令注入系统 <code>init.rc</code> 的机制。这使得模块可以在不修改系统分区的情况下注册自定义的 Android 服务、设置属性触发器或执行其他 Init 语言操作。</p><p>在启动过程中，KernelSU 的内核模块通过 hook <code>read()</code> 和 <code>fstat()</code> 系统调用，在 Android init 进程读取 <code>/system/etc/init/hw/init.rc</code> 时，将自定义 RC 内容透明地追加到文件末尾。init 进程会像处理原始 init.rc 内容一样解析这些注入的指令。</p><p>在用户空间侧，ksud 会将所有已启用模块的 <code>.rc</code> 文件合并到一个 <code>modules.rc</code> 文件中，存放在 <code>/metadata</code> 分区上。每当模块状态发生变化（安装、启用、禁用、卸载等）时，这个文件都会被自动重新生成。</p><h4 id="模块-initrc-文件" tabindex="-1">模块 initrc 文件 <a class="header-anchor" href="#模块-initrc-文件" aria-label="Permalink to &quot;模块 initrc 文件&quot;">​</a></h4><p>在模块目录中创建一个 <code>initrc/</code> 子目录，将 <code>.rc</code> 文件放置其中：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>文件必须以 <code>.rc</code> 为扩展名。</li><li>只要模块处于启用状态，<code>initrc/</code> 目录下的所有 <code>.rc</code> 文件都会被包含（无需设置可执行权限）。</li><li>处理的先后顺序为：同一目录内的文件按<strong>文件名字母顺序</strong>排列；模块之间按<strong>模块 ID 字母顺序</strong>排列。</li></ul></div><h4 id="通用-initrc-文件" tabindex="-1">通用 initrc 文件 <a class="header-anchor" href="#通用-initrc-文件" aria-label="Permalink to &quot;通用 initrc 文件&quot;">​</a></h4><p>除了模块级别的 RC 文件外，你还可以将 <code>.rc</code> 文件放置在全局目录中：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">全局 initrc 文件需要可执行权限</p><p>与模块 <code>initrc/</code> 目录不同，<code>/data/adb/initrc.d/</code> 中的文件<strong>必须设置可执行权限</strong>才会被包含。不具有可执行权限的 <code>.rc</code> 文件会被静默跳过。</p></div><p>全局 <code>initrc.d/</code> 文件在所有模块 RC 文件之前被处理。</p><h4 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h4><p>以下是一个注册自定义 Android 服务的 <code>.rc</code> 文件示例：</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>此文件放置在 <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>，将在系统启动时注册一个名为 <code>myservice</code> 的服务，并在 <code>sys.boot_completed=1</code> 时启动它。</p><h4 id="手动刷新" tabindex="-1">手动刷新 <a class="header-anchor" href="#手动刷新" aria-label="Permalink to &quot;手动刷新&quot;">​</a></h4><p>你可以通过以下命令手动触发 <code>modules.rc</code> 重新生成（更改将在下次启动时生效）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>initrc 注入发生在启动极早期（init 读取 init.rc 时），<strong>早于</strong> post-fs-data 和所有模块脚本的执行。</li><li>注入的 RC 内容被 init 当作原始 init.rc 的一部分处理，支持所有 Android Init 语言语法（服务定义、触发器、属性设置等）。</li><li>在 <strong>late-load 模式</strong>下，initrc 注入<strong>不可用</strong>，因为系统调用 hook 在该模式下不会被安装。</li><li>可以在 ksud 修补镜像的时候传入参数<code>--no-custom-rc</code> 禁用模块 RC 注入。</li></ul></div><h3 id="preinit" tabindex="-1">preinit <a class="header-anchor" href="#preinit" aria-label="Permalink to &quot;preinit {#preinit}&quot;">​</a></h3><p>模块可以在 <strong>SELinux 策略加载之前、init 解析 init.rc 之前</strong>执行一些操作，比如加载内核模块、运行静态程序、写 procfs/sysfs。把这些操作放在 <code>preinit/</code> 目录里，由 <code>preinit/preinit.conf</code> 描述：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── preinit/</span></span>
<span class="line"><span>│   ├── preinit.conf</span></span>
<span class="line"><span>│   ├── kmod/foo.ko</span></span>
<span class="line"><span>│   └── bin/fixup</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>ksud 会把每个已启用模块的整个 <code>preinit/</code> 目录复制到 <code>/metadata</code> 分区。下次开机时，KernelSU 内核模块里内嵌的 runner 会在 first stage init 执行 <code>/system/bin/init selinux_setup</code> 的时候运行这些操作。此时 <code>/metadata</code>、<code>/system</code>、<code>/vendor</code> 已经挂载，<code>/proc</code>、<code>/sys</code>、<code>/dev</code> 可用，但还没有任何策略，property service 和 ueventd 也都没有运行。模块按模块 ID 的字母顺序处理。</p><h4 id="preinit-conf" tabindex="-1">preinit.conf <a class="header-anchor" href="#preinit-conf" aria-label="Permalink to &quot;preinit.conf&quot;">​</a></h4><p>每行一个动作。<code>#</code> 开头的行和空行会被忽略。参数之间用空白分隔；用双引号保留参数中的空白，用 <code>\\&quot;</code>、<code>\\\\</code> 表示引号和反斜杠本身。<strong>不做</strong>任何变量展开。相对路径以模块的 preinit 目录为基准。单行最长 4 KB，整个文件最大 64 KB。</p><table tabindex="0"><thead><tr><th>动作</th><th>语法</th><th>语义</th></tr></thead><tbody><tr><td><code>insmod</code></td><td><code>insmod &lt;ko&gt; [params...]</code></td><td>加载内核模块。会先从内核 kallsyms 查询未定义符号并写入符号表，再用 <code>init_module</code> 加载，所以模块可以使用未导出的符号；不需要绑定符号的模块直接用 <code>finit_module</code> 加载。多个参数用空格拼接</td></tr><tr><td><code>exec</code></td><td><code>exec [-t &lt;ms&gt;] &lt;prog&gt; [args...]</code></td><td>运行程序并等待其退出，退出码非 0 视为失败。默认 5000 ms 后被杀掉</td></tr><tr><td><code>write</code></td><td><code>write &lt;path&gt; &lt;content&gt;</code></td><td>向已存在的文件写入 <code>content</code>，不追加换行，用于 procfs/sysfs</td></tr></tbody></table><p>动作名加 <code>?</code> 后缀表示失败可忽略。其他动作失败时会中止<strong>当前模块</strong>剩余的动作，后面的模块照常执行。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># preinit/preinit.conf</span></span>
<span class="line"><span>insmod   kmod/foo.ko  debug=1 name=&quot;a b&quot;</span></span>
<span class="line"><span>insmod?  kmod/optional.ko</span></span>
<span class="line"><span>exec -t 10000  bin/fixup --flag</span></span>
<span class="line"><span>write    /proc/sys/kernel/printk_devkmsg on</span></span></code></pre></div><p><code>exec</code> 启动的程序以 root 运行，拥有完整的 capabilities，不受 SELinux 约束。工作目录是模块的 preinit 目录，stdin 接 <code>/dev/null</code>，stdout/stderr 按行转发到内核日志，带 <code>ksu_preinit[&lt;MODID&gt;]:</code> 前缀。环境变量只有 <code>KSU=true</code>、<code>KSU_PREINIT=1</code>、<code>MODID</code>、<code>PREINIT_DIR</code> 和 <code>PATH=/system/bin:/vendor/bin</code>。</p><div class="warning custom-block"><p class="custom-block-title">限制</p><ul><li>没有 shell：只能使用<strong>静态链接</strong>的程序，因为 <code>/apex</code> 还没有挂载。</li><li><code>/dev</code> 下只有 first stage init 创建的节点，ueventd 没有运行。</li><li>固件加载没有用户态回退，固件只能由内核直接从 <code>/vendor/firmware</code> 等路径加载。</li><li>不能读写属性。</li><li>只有 first stage 的 vendor 模块已经加载，依赖 vendor_dlkm（second stage 才加载）中符号的 <code>.ko</code> 会加载失败。</li><li>不允许常驻：preinit 结束时残留的进程都会被杀掉。整个 preinit 阶段最多 30 秒。</li><li>改动在<strong>下次开机</strong>生效，热安装不会执行 preinit。</li><li>目录和 <code>preinit.conf</code>（以及用到的 <code>.ko</code>、程序文件）的属主必须是 root，且 group/other 不可写。ksud 复制时会自动处理。</li><li>ksud 复制时保留文件原有的权限位（去掉 group/other 写权限）。安装器会把模块文件设为 <code>0644</code>，所以 <code>exec</code> 要运行的程序需要在 <code>customize.sh</code> 里 <code>set_perm $MODPATH/preinit/bin/xxx 0 0 0755</code>。</li></ul></div><h4 id="metadata-空间" tabindex="-1">/metadata 空间 <a class="header-anchor" href="#metadata-空间" aria-label="Permalink to &quot;/metadata 空间&quot;">​</a></h4><p><code>/metadata</code> 很小（通常只有 10 MB 左右），里面还放着加密密钥和 OTA 状态。因此 ksud 至少保留 8 MB 空闲空间，preinit 最多占用 4 MB。模块按 ID 字母顺序依次复制，放不下的模块会被整个跳过，安装时也会给出提示。可以用下面的命令查看结果：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preinit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><h4 id="防砖" tabindex="-1">防砖 <a class="header-anchor" href="#防砖" aria-label="Permalink to &quot;防砖&quot;">​</a></h4><p>runner 执行任何动作前会把启动计数加 1，开机完成后由 ksud 清零。连续 3 次开机没有完成时，preinit 会被跳过，并保持禁用，直到某个模块的 preinit 内容发生变化，或者手动执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preinit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span></span></code></pre></div><p>关机充电模式下不会执行 preinit；安全模式会禁用所有模块，下次开机时它们的 preinit 内容也会被移除。如果需要手动救砖，可以在 recovery 里删除 <code>/metadata/vold/ksu/preinit</code>（或 <code>/metadata/watchdog/ksu/preinit</code>、<code>/metadata/ksu/preinit</code>，以实际存在的为准），或者 <code>fastboot boot</code> 原厂镜像后删除。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>在 <strong>late-load 模式</strong>下以及不使用两阶段 init 的设备（Android 10 之前以 system-as-root 出厂的设备）上，preinit <strong>不可用</strong>。</li><li>当前内核不执行 preinit 时（late-load 模式、<code>preinit=0</code>，或内核编译时未包含 preinit），ksud 不会向 <code>/metadata</code> 拷贝任何内容，<code>ksud module preinit status</code> 会把这些模块标为 <code>unsupported</code>。</li><li>可以通过 KernelSU 内核模块参数 <code>preinit=0</code> 彻底关闭 preinit，<code>ksud boot-patch</code> / <code>boot-patch-v2</code> 的 <code>--no-preinit</code> 选项会设置它。</li><li>能写入 <code>/metadata</code> 就等于能在这么早的阶段执行代码，请只安装可信的模块。</li></ul></div><h2 id="module-installer" tabindex="-1">模块安装包 <a class="header-anchor" href="#module-installer" aria-label="Permalink to &quot;模块安装包 {#module-installer}&quot;">​</a></h2><p>KernelSU 的模块安装包就是一个可以通过 KernelSU 管理器 APP 刷入的 zip 文件，此 zip 文件的格式如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Optional, more details later)</span></span>
<span class="line"><span>│                                           This script will be sourced by update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* 其他模块文件 */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>KernelSU 模块不支持在 Recovery 中安装！！</p></div><h3 id="customizing-installation" tabindex="-1">定制安装过程 <a class="header-anchor" href="#customizing-installation" aria-label="Permalink to &quot;定制安装过程 {#customizing-installation}&quot;">​</a></h3><p>如果你想控制模块的安装过程，可以在模块的目录下创建一个名为 <code>customize.sh</code> 的文件，这个脚本将会在模块被解压后<strong>导入</strong>到当前 shell 中，如果你的模块需要根据设备的 API 版本或者设备构架做一些额外的操作，那这个脚本将非常有用。</p><p>如果你想完全控制脚本的安装过程，你可以在 <code>customize.sh</code> 中声明 <code>SKIPUNZIP=1</code> 来跳过所有的默认安装步骤；此时，你需要自行处理所有安装过程（如解压模块，设置权限等）</p><p><code>customize.sh</code> 脚本以“独立模式”运行在 KernelSU 的 BusyBox <code>ash</code> shell 中。你可以使用如下变量和函数：</p><h4 id="variables" tabindex="-1">变量 <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;变量 {#variables}&quot;">​</a></h4><ul><li><code>KSU</code> (bool): 标记此脚本运行在 KernelSU 环境下，此变量的值将永远为 <code>true</code>，你可以通过它区分 Magisk。</li><li><code>KSU_VER</code> (string): KernelSU 当前的版本名字 (如： <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): KernelSU 用户空间当前的版本号 (如. <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): KernelSU 内核空间当前的版本号 (如. <code>10672</code>)</li><li><code>BOOTMODE</code> (bool): 此变量在 KernelSU 中永远为 <code>true</code></li><li><code>MODPATH</code> (path): 当前模块的安装目录</li><li><code>TMPDIR</code> (path): 可以存放临时文件的目录</li><li><code>ZIPFILE</code> (path): 当前模块的安装包文件</li><li><code>ARCH</code> (string): 设备的 CPU 构架，有如下几种： <code>arm</code>, <code>arm64</code>, <code>x86</code>, or <code>x64</code></li><li><code>IS64BIT</code> (bool): 是否是 64 位设备</li><li><code>API</code> (int): 当前设备的 Android API 版本 (如：Android 6.0 上为 <code>23</code>)</li><li><code>KSU_UAPI_VER</code> (int): KernelSU 用户空间 (ksud) 的 UAPI 版本号 (如：<code>2</code>)。当内核驱动发生破坏性更改时此版本号会递增，模块可据此判断兼容性。</li><li><code>KSU_RUNTIME_MODE</code> (string): KernelSU 当前的运行模式。可能的值为 <code>built-in</code>（即 GKI 模式，编译进内核）、<code>lkm</code>（开机时作为内核模块加载）或 <code>late-load</code>（开机后作为内核模块加载）。</li><li><code>KSU_LATE_LOAD</code> (int?): 如果 KernelSU 是在开机后延迟加载的，此变量的值为 <code>1</code>，否则不设置此变量。</li><li><code>KSU_HAS_HOT_INSTALL</code> (bool): 安装程序支持<a href="#hot-install">热安装</a>时为 <code>true</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>MAGISK_VER_CODE</code> 在 KernelSU 中永远为 <code>25200</code>，<code>MAGISK_VER</code> 则为 <code>v25.2</code>，请不要通过这两个变量来判断是否是 KernelSU！</p></div><h4 id="functions" tabindex="-1">函数 <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;函数 {#functions}&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    print &lt;msg&gt; to console</span></span>
<span class="line"><span>    Avoid using &#39;echo&#39; as it will not display in custom recovery&#39;s console</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    print error message &lt;msg&gt; to console and terminate the installation</span></span>
<span class="line"><span>    Avoid using &#39;exit&#39; as it will skip the termination cleanup steps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    this function is a shorthand for the following commands:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    if [context] is not set, the default is &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    for all files in &lt;directory&gt;, it will call:</span></span>
<span class="line"><span>       set_perm file owner group filepermission context</span></span>
<span class="line"><span>    for all directories in &lt;directory&gt; (including itself), it will call:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h3 id="hot-install" tabindex="-1">热安装 <a class="header-anchor" href="#hot-install" aria-label="Permalink to &quot;热安装 {#hot-install}&quot;">​</a></h3><p>默认情况下，新安装或更新的模块会被放在 <code>/data/adb/modules_update</code> 中，重启后才会生效。如果你的模块不依赖只在开机时才会进行的操作，可以在 <code>customize.sh</code> 中请求 KernelSU 立即应用：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># customize.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_HOT_INSTALL_REQUEST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选：新版本生效后要执行的模块内脚本</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MODULE_HOT_RUN_SCRIPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hotinstall.sh</span></span></code></pre></div><p>这个请求在安装时判断，因此由模块自己决定是否需要重启，例如只在新版本没有改动 <code>system</code> 下的文件时才请求热安装。</p><p>安装脚本（包括 <code>customize.sh</code> 和元模块的 <code>metainstall.sh</code>）成功结束后，KernelSU 会：</p><ol><li>用新版本替换 <code>/data/adb/modules/&lt;id&gt;</code>。旧目录会被移走，下次开机时才删除，因此仍在使用旧版本的进程和挂载在此之前可以继续工作。</li><li>加载模块的 <code>sepolicy.rule</code>。规则只会增加，新版本删掉的规则在重启前仍然有效。</li><li>执行 <code>MODULE_HOT_RUN_SCRIPT</code>（相对于模块目录的路径），方式与启动脚本相同：运行在全局 mount 命名空间中，工作目录为脚本所在目录。脚本输出会显示在安装界面中，stdin 为 <code>/dev/null</code>，并忽略 <code>SIGPIPE</code>，因此安装程序退出后后台进程不会被杀掉。安装程序最多等待 30 秒，长期运行的服务请放到后台启动。脚本不存在时会跳过。</li><li>不留下 <code>update</code> 标记，管理器不会提示重启。</li></ol><p>即使 <code>sepolicy.rule</code> 加载失败、脚本执行失败或超时，模块仍视为热安装成功，请留意安装输出。</p><p>和普通安装一样，即使旧版本处于禁用状态，安装后模块也会被启用。</p><p>立即生效：模块文件本身、WebUI、<code>action.sh</code> 以及 <code>module.prop</code> 中的信息。</p><p>下次开机才生效：<code>system</code> 及其他分区目录下的文件（由元模块挂载）、<code>system.prop</code>、<code>initrc</code>、<code>preinit</code>，以及 <code>post-fs-data.sh</code>、<code>post-mount.sh</code>、<code>service.sh</code>、<code>boot-completed.sh</code> 这几个阶段。热安装时<strong>不会</strong>执行它们，但之后每次开机仍会照常执行。如果需要它们立即生效，请在 <code>MODULE_HOT_RUN_SCRIPT</code> 中处理，例如启动你的服务或调用 <code>resetprop</code>。</p><p>KernelSU 不会替你停止旧版本，更新时也不会执行 <code>uninstall.sh</code>。如果你的模块运行了守护进程，<code>MODULE_HOT_RUN_SCRIPT</code> 应先停止旧实例再启动新实例。</p><p>以下情况 KernelSU 会回退为重启后生效，并打印原因：</p><ul><li>正在安装的是元模块。</li><li>设备处于安全模式。</li><li><code>MODULE_HOT_RUN_SCRIPT</code> 不是指向模块内文件的相对路径（指向模块外的符号链接会被拒绝）。</li><li>无法替换模块目录。</li></ul><h2 id="boot-scripts" tabindex="-1">启动脚本 <a class="header-anchor" href="#boot-scripts" aria-label="Permalink to &quot;启动脚本 {#boot-scripts}&quot;">​</a></h2><p>在 KernelSU 中，根据脚本运行模式的不同分为两种：post-fs-data 模式和 late_start 服务模式。</p><ul><li><p>post-fs-data 模式</p><ul><li>这个阶段是阻塞的。在执行完成之前或者 10 秒钟之后，启动过程会暂停。</li><li>脚本在任何模块被挂载之前运行。这使得模块开发者可以在模块被挂载之前动态地调整它们的模块。</li><li>这个阶段发生在 Zygote 启动之前。</li><li>使用 setprop 会导致启动过程死锁！请使用 <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> 代替。</li><li><strong>只有在必要时才在此模式下运行脚本</strong>。</li></ul></li><li><p>late_start 服务模式</p><ul><li>这个阶段是非阻塞的。你的脚本会与其余的启动过程<strong>并行</strong>运行。</li><li><strong>大多数脚本都建议在这种模式下运行</strong>。</li></ul></li></ul><p>在 KernelSU 中，启动脚本根据存放位置的不同还分为两种：通用脚本和模块脚本。</p><ul><li><p>通用脚本</p><ul><li>放置在 <code>/data/adb/post-fs-data.d</code>, <code>/data/adb/post-mount.d</code>, <code>/data/adb/service.d</code> 或 <code>/data/adb/boot-completed.d</code> 中。</li><li>只有在脚本被设置为可执行（<code>chmod +x script.sh</code>）时才会被执行。</li><li>在 <code>post-fs-data.d</code> 中的脚本以 post-fs-data 模式运行，在 <code>service.d</code> 中的脚本以 late_start 服务模式运行。</li><li>模块<strong>不应</strong>在安装过程中添加通用脚本。</li></ul></li><li><p>模块脚本</p><ul><li>放置在模块自己的文件夹中。</li><li>只有当模块被启用时才会执行。</li><li><code>post-fs-data.sh</code> 以 post-fs-data 模式运行，<code>post-mount.sh</code> 以 post-mount 模式运行，而 <code>service.sh</code> 则以 late_start 服务模式运行，<code>boot-completed.sh</code> 在 Android 系统启动完毕后以服务模式运行。</li></ul></li></ul><p>所有启动脚本都将在 KernelSU 的 BusyBox ash shell 中运行，并启用“独立模式”。</p><h3 id="Boot-scripts-process-explanation" tabindex="-1">启动脚本的流程解疑 <a class="header-anchor" href="#Boot-scripts-process-explanation" aria-label="Permalink to &quot;启动脚本的流程解疑 {#Boot-scripts-process-explanation}&quot;">​</a></h3><p>以下是 Android 的相关启动流程（部分省略），其中包括了 KernelSU 的操作（带前导星号），应该能帮助你更好地理解这些启动脚本的用途：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0. Bootloader (nothing on screen)</span></span>
<span class="line"><span>load patched boot.img</span></span>
<span class="line"><span>load kernel:</span></span>
<span class="line"><span>    - GKI mode: GKI kernel with KernelSU integrated</span></span>
<span class="line"><span>    - LKM mode: stock kernel</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. kernel exec init (oem logo on screen):</span></span>
<span class="line"><span>    - GKI mode: stock init</span></span>
<span class="line"><span>    - LKM mode: exec ksuinit, insmod kernelsu.ko, exec stock init</span></span>
<span class="line"><span>mount /dev, /dev/pts, /proc, /sys, etc.</span></span>
<span class="line"><span>  *preinit: before loading SELinux policy, the kernel runs modules&#39; preinit.conf</span></span>
<span class="line"><span>property-init -&gt; read default props</span></span>
<span class="line"><span>read init.rc</span></span>
<span class="line"><span>  *initrc injection: Kernel hook appends KernelSU core RC and module modules.rc to init.rc</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>early-init -&gt; init -&gt; late_init</span></span>
<span class="line"><span>early-fs</span></span>
<span class="line"><span>   start vold</span></span>
<span class="line"><span>fs</span></span>
<span class="line"><span>  mount /vendor, /system, /persist, etc.</span></span>
<span class="line"><span>post-fs-data</span></span>
<span class="line"><span>  *safe mode check</span></span>
<span class="line"><span>  *execute general scripts in post-fs-data.d/</span></span>
<span class="line"><span>  *load sepolicy.rule</span></span>
<span class="line"><span>  *mount tmpfs</span></span>
<span class="line"><span>  *execute module scripts post-fs-data.sh</span></span>
<span class="line"><span>    **(Zygisk)./bin/zygisk-ptrace64 monitor</span></span>
<span class="line"><span>  *(pre)load system.prop (same as resetprop -n)</span></span>
<span class="line"><span>  *remount modules /system</span></span>
<span class="line"><span>  *execute general scripts in post-mount.d/</span></span>
<span class="line"><span>  *execute module scripts post-mount.sh</span></span>
<span class="line"><span>zygote-start</span></span>
<span class="line"><span>load_all_props_action</span></span>
<span class="line"><span>  *execute resetprop (actual set props for resetprop with -n option)</span></span>
<span class="line"><span>... -&gt; boot</span></span>
<span class="line"><span>  class_start core</span></span>
<span class="line"><span>    start-service logd, console, vold, etc.</span></span>
<span class="line"><span>  class_start main</span></span>
<span class="line"><span>    start-service adb, netd (iptables), zygote, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. kernel2user init (rom animation on screen, start by service bootanim)</span></span>
<span class="line"><span>*execute general scripts in service.d/</span></span>
<span class="line"><span>*execute module scripts service.sh</span></span>
<span class="line"><span>*set props for resetprop without -p option</span></span>
<span class="line"><span>  **(Zygisk) hook zygote (start zygiskd)</span></span>
<span class="line"><span>  **(Zygisk) mount zygisksu/module.prop</span></span>
<span class="line"><span>start system apps (autostart)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>boot complete (broadcast ACTION_BOOT_COMPLETED event)</span></span>
<span class="line"><span>*execute general scripts in boot-completed.d/</span></span>
<span class="line"><span>*execute module scripts boot-completed.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. User operable (lock screen)</span></span>
<span class="line"><span>input password to decrypt /data/data</span></span>
<span class="line"><span>*actual set props for resetprop with -p option</span></span>
<span class="line"><span>start user apps (autostart)</span></span></code></pre></div><p>如果你对 Android 的 init 语言感兴趣，推荐阅读<a href="https://android.googlesource.com/platform/system/core/+/master/init/README.md" target="_blank" rel="noreferrer">文档</a>。</p><h2 id="late-load-mode" tabindex="-1">Late-load 模式 <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Late-load 模式 {#late-load-mode}&quot;">​</a></h2><p>除了上述标准启动流程外，KernelSU 还支持 <strong>late-load 模式</strong>，用于 LKM（可加载内核模块）场景。在该模式下，KernelSU 内核模块在<strong>系统完全启动后</strong>加载，而非在 init 过程中加载。</p><h3 id="什么时候触发-late-load" tabindex="-1">什么时候触发 late-load？ <a class="header-anchor" href="#什么时候触发-late-load" aria-label="Permalink to &quot;什么时候触发 late-load？&quot;">​</a></h3><p>通过运行 <code>ksud late-load</code> 命令触发。该命令会：</p><ol><li>检测当前 KMI 版本，从内嵌资源中加载对应的 <code>kernelsu.ko</code>。</li><li>执行模块初始化（SELinux 规则、白名单、feature 等），这些工作在标准启动中发生在 boot 阶段。</li></ol><p>由于系统已经完全运行，某些启动时的机制不可用或不需要。</p><h3 id="与标准启动的差异" tabindex="-1">与标准启动的差异 <a class="header-anchor" href="#与标准启动的差异" aria-label="Permalink to &quot;与标准启动的差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行为</th><th style="text-align:center;">标准启动</th><th style="text-align:center;">Late-load 模式</th></tr></thead><tbody><tr><td>内核模块由 init (PID 1) 加载</td><td style="text-align:center;">是</td><td style="text-align:center;">否（启动后加载）</td></tr><tr><td>initrc 注入（模块 <code>.rc</code> 文件注入 init.rc）</td><td style="text-align:center;">是</td><td style="text-align:center;">不可用</td></tr><tr><td>preinit（模块 <code>preinit/preinit.conf</code>）</td><td style="text-align:center;">是</td><td style="text-align:center;">不可用</td></tr><tr><td>ksud 的 kprobe 钩子 (execve/read/fstat/input)</td><td style="text-align:center;">是</td><td style="text-align:center;">跳过</td></tr><tr><td>安全模式检测（音量键）</td><td style="text-align:center;">是</td><td style="text-align:center;">始终禁用</td></tr><tr><td>启动日志抓取 (logcat/dmesg)</td><td style="text-align:center;">是</td><td style="text-align:center;">跳过</td></tr><tr><td>Magisk 共存检测</td><td style="text-align:center;">是</td><td style="text-align:center;">跳过</td></tr><tr><td><code>post-fs-data</code> 事件通知内核</td><td style="text-align:center;">是</td><td style="text-align:center;">跳过</td></tr><tr><td><code>boot-completed</code> 事件通知内核</td><td style="text-align:center;">是</td><td style="text-align:center;">初始化时直接设置</td></tr><tr><td><code>post-fs-data.sh</code> / <code>post-fs-data.d/</code> 脚本</td><td style="text-align:center;">是</td><td style="text-align:center;">由 <code>late-load</code> 阶段替代</td></tr><tr><td><code>system.prop</code> 加载</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td>OverlayFS 挂载（metamodule）</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>post-mount.sh</code> / <code>post-mount.d/</code> 脚本</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>service.sh</code> / <code>service.d/</code> 脚本</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>boot-completed.sh</code> / <code>boot-completed.d/</code> 脚本</td><td style="text-align:center;">是</td><td style="text-align:center;">是</td></tr><tr><td><code>KSU_LATE_LOAD</code> 环境变量</td><td style="text-align:center;">未设置</td><td style="text-align:center;">设置为 <code>1</code></td></tr><tr><td>内核 info 标志位 <code>0x4</code></td><td style="text-align:center;">未设置</td><td style="text-align:center;">已设置</td></tr></tbody></table><h3 id="脚本执行顺序" tabindex="-1">脚本执行顺序 <a class="header-anchor" href="#脚本执行顺序" aria-label="Permalink to &quot;脚本执行顺序&quot;">​</a></h3><p>在 late-load 模式下，脚本执行顺序如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. 加载 kernelsu.ko（如果尚未加载）</span></span>
<span class="line"><span>  2. 释放二进制文件、处理模块更新、加载 SELinux 规则、初始化 feature</span></span>
<span class="line"><span>  3. 执行 late-load.d/ 通用脚本和模块的 late-load 脚本（阻塞）</span></span>
<span class="line"><span>  4. 加载 system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. 执行 metamodule mount 脚本（OverlayFS 挂载）</span></span>
<span class="line"><span>  6. 执行 post-mount.d/ 通用脚本和模块的 post-mount.sh（阻塞）</span></span>
<span class="line"><span>  7. 执行 service.d/ 通用脚本和模块的 service.sh（非阻塞）</span></span>
<span class="line"><span>  8. 执行 boot-completed.d/ 通用脚本和模块的 boot-completed.sh（非阻塞）</span></span></code></pre></div><h3 id="late-load-专用脚本" tabindex="-1">Late-load 专用脚本 <a class="header-anchor" href="#late-load-专用脚本" aria-label="Permalink to &quot;Late-load 专用脚本&quot;">​</a></h3><p>模块可以提供 <code>late-load.sh</code> 脚本，该脚本<strong>仅在 late-load 模式下运行</strong>，作为 <code>post-fs-data.sh</code> 的替代。该脚本在 OverlayFS 挂载之前运行，与标准流程中的 <code>post-fs-data.sh</code> 时机类似。</p><p>此外，通用脚本可以放置在 <code>/data/adb/late-load.d/</code> 目录下，在该阶段执行。</p><h3 id="在脚本中检测-late-load-模式" tabindex="-1">在脚本中检测 late-load 模式 <a class="header-anchor" href="#在脚本中检测-late-load-模式" aria-label="Permalink to &quot;在脚本中检测 late-load 模式&quot;">​</a></h3><p>模块可以通过 <code>KSU_LATE_LOAD</code> 环境变量检测当前是否处于 late-load 模式：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 当前处于 late-load 模式</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>这使得模块可以据此调整自身行为，例如跳过仅在早期启动时才需要的操作。</p>`,141)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
